"],"pricePerPerson":78,"longitude":null,"latitude":null,"status":"draft"},"original":{"priceClaim":"平台人均78元人民币，问卷一人70人民币","dishes":["辣冒烟牛肉","鸭血","三角粑"],"hours":"周一至周五11:00–23:30，周六至周日11:00–24:00","deliveryClaim":"前山/玖洲道片区，条件待确认","sourceClaim":"高德地图POI、本地美食攻略，未附链接","businessClaim":"报告称正常营业"},"issues":["保留问卷70元与报告78元两个来源，不将差异视为错误或精确实时报价","横琴、十字门等配送范围未核实"],"priceDecision":"人民币单值仅在资料明确时暂存；区间或澳门元原价保留在原始资料，人民币字段留空"},{"sourceKey":"survey-dali","operation":"create_draft","input":{"name":"大力烤肉饭（澳门绿杨花园店）","nameEn":null,"address":"澳门花地玛堂区俾若翰街449号地下L铺绿杨花园（原文楼座信息待核实）","categorySlug":"food","region":"macau-peninsula","tagSlugs":["fast-food","barbecue","delivery","late-night"],"searchKeywords":["澳门烤肉饭","澳门外卖","大力烤肉饭","三拼烤肉饭","黑椒牛肉饭","流心蛋烤肉饭"],"pricePerPerson":null,"longitude":null,"latitude":null,"status":"draft"},"original":{"currency":"MOP","priceClaim":"人均约70–88澳门元；三拼饭78MOP；问卷88MOP","hours":"10:30–次日02:30","businessClaim":"报告称正常营业","deliveryClaim":"报告称澳门半岛、氹仔高校片区可配送，具体条件未核实","sourceClaim":"高德地图POI、澳门本地美食攻略，未附链接","addressClaim":"澳门特别行政区/花地玛堂区/俾若翰街449号地下L铺绿杨花园（第一座利康阁第三座）"},"issues":["网站金额字段统一人民币，未提供汇率与日期，不将70/78/88澳门元写成人民币","原文第一座/第三座楼座表述有歧义","配送到指定高校和氹仔的说法缺少条件，未作为已核实承诺","未添加氹仔美食关键词，实际门店位于澳门半岛"],"priceDecision":"人民币单值仅在资料明确时暂存；区间或澳门元原价保留在原始资料，人民币字段留空"},{"sourceKey":"survey-ydm","operation":"create_draft","input":{"name":"YDM医帝庙凉茶（北山店）","nameEn":"YDM Bistro & Colortea","address":"珠海市香洲区南屏镇北山正街78-5号（医帝庙旧址）","categorySlug":"entertainment","region":"zhuhai","tagSlugs":["bar","late-night"],"searchKeywords":["北山文创","凉茶酒吧","珠海清吧","日茶夜酒","廿四味凉茶","五花茶","凉茶特调鸡尾酒","医帝庙"],"pricePerPerson":null,"longitude":null,"latitude":null,"status":"draft"},"original":{"priceClaim":"白天凉茶20–30元人民币，夜间酒吧60–80元人民币，整体61–83元人民币","hours":"11:00–18:00凉茶；19:00–次日02:00酒吧","businessClaim":"报告称正常营业","service":"堂食，小型聚会；外卖待确认","sourceClaim":"高德地图POI、Trip.com探店攻略，未附链接"},"issues":["按问卷主要酒吧场景归娱乐/酒吧，保留日间凉茶与日茶夜酒关键词；不创建两个重复门店","各时段价格口径不同，单个人均留空","未核实外卖，不添加可外卖标签","未核实学生或团体优惠，不添加优惠标签"],"priceDecision":"人民币单值仅在资料明确时暂存；区间或澳门元原价保留在原始资料，人民币字段留空"}]}$batch$::jsonb;
  v_entry jsonb;
  v_input jsonb;
  v_tags jsonb;
  v_id uuid;
  v_matches uuid[];
  v_existing public.places%rowtype;
  v_disposition text;
  v_processed integer:=0;
begin
  if jsonb_array_length(v_batch->'entries')<>47 then raise exception 'Expected 43 screenshot rows and 4 questionnaire rows'; end if;
  for v_entry in select value from jsonb_array_elements(v_batch->'entries') loop
    if exists(select 1 from public.admin_audit_logs a join public.places p on p.id::text=a.entity_id
      where a.metadata->>'batch_id'=v_batch->>'batchId' and a.metadata->>'source_key'=v_entry->>'sourceKey'
        and a.entity_type='place' and a.action in ('place.import_draft','place.source_attached')) then
      v_processed:=v_processed+1;
      continue;
    end if;
    v_id:=null;
    v_input:=null;
    if v_entry->>'operation'='attach_source' then
      select * into v_existing from public.places where id=(v_entry->>'targetId')::uuid;
      if not found then raise exception 'Linked place disappeared: %',v_entry->>'targetName'; end if;
      v_id:=v_existing.id;
      v_disposition:='source_attached_without_overwriting_corrections';
    elsif v_entry->>'operation'='create_draft' then
      if v_entry->'input'->>'status'<>'draft' or v_entry->'input'->>'longitude' is not null
        or v_entry->'input'->>'latitude' is not null then raise exception 'Draft-only import required'; end if;
      select jsonb_agg(t.id order by x.ordinality) into v_tags
        from jsonb_array_elements_text(v_entry->'input'->'tagSlugs') with ordinality x(slug,ordinality)
        join public.tags t on t.slug=x.slug and t.is_active;
      if jsonb_array_length(v_tags) is distinct from jsonb_array_length(v_entry->'input'->'tagSlugs') then
        raise exception 'Missing tag for %',v_entry->>'sourceKey';
      end if;
      v_input := ((v_entry->'input') - 'tagSlugs') || jsonb_build_object('tagIds',v_tags);
      perform private.assert_place_editor_input(v_input);
      select array_agg(p.id) into v_matches from public.places p
        where regexp_replace(translate(p.name,'（）','()'),'\s+','','g')=
          regexp_replace(translate(v_input->>'name','（）','()'),'\s+','','g');
      if coalesce(cardinality(v_matches),0)>1 then raise exception 'Ambiguous duplicate for %',v_input->>'name'; end if;
      if coalesce(cardinality(v_matches),0)=1 then
        v_id:=v_matches[1];
        select * into v_existing from public.places where id=v_id;
        v_disposition:='matching_name_preserved_without_overwrite';
      else
        insert into public.places(name,name_en,address,category_slug,region,longitude,latitude,price_per_person,
          status,published_at,created_by,search_keywords_manual)
        values(v_input->>'name',v_input->>'nameEn',v_input->>'address',v_input->>'categorySlug',v_input->>'region',
          null,null,(v_input->>'pricePerPerson')::numeric,'draft',null,null,
          array(select jsonb_array_elements_text(v_input->'searchKeywords')))
        returning id into v_id;
        insert into public.place_tags(place_id,tag_id)
          select v_id,value::uuid from jsonb_array_elements_text(v_tags);
        select * into v_existing from public.places where id=v_id;
        v_disposition:='new_draft';
      end if;
    else raise exception 'Unknown operation'; end if;
    insert into public.admin_audit_logs(actor_id,action,entity_type,entity_id,note,metadata)
    values(null,case when v_disposition='new_draft' then 'place.import_draft' else 'place.source_attached' end,
      'place',v_id::text,'完整截图摘要/问卷资料归档；待核实草稿，保留不同来源与币种，不冒用管理员身份。',
      jsonb_build_object('batch_id',v_batch->>'batchId','source_key',v_entry->>'sourceKey','operator','supabase_mcp',
        'disposition',v_disposition,'verification',v_batch->>'verification','rules',v_batch->'rules',
        'source_entry',v_entry,'after',to_jsonb(v_existing),'editor_input',v_input));
    v_processed:=v_processed+1;
  end loop;
  if v_processed<>47 then raise exception 'Incomplete reconciliation'; end if;
end $import$;

select jsonb_build_object(
  'source_rows',count(*),
  'new_drafts',count(*) filter(where a.metadata->>'disposition'='new_draft'),
  'linked_sources',count(*) filter(where a.metadata->>'disposition'='source_attached_without_overwriting_corrections'),
  'other_existing_matches',count(*) filter(where a.metadata->>'disposition'='matching_name_preserved_without_overwrite'),
  'invalid_new_drafts',count(*) filter(where a.metadata->>'disposition'='new_draft'
    and (p.status<>'draft' or p.longitude is not null or p.latitude is not null or p.published_at is not null)),
  'total_places',(select count(*) from public.places),
  'total_drafts',(select count(*) from public.places where status='draft'),
  'published',(select count(*) from public.places where status='published')
) as reconciliation
from public.admin_audit_logs a join public.places p on p.id::text=a.entity_id
where a.metadata->>'batch_id'='complete-screenshots-and-survey-2026-10-17'
  and a.action in ('place.import_draft','place.source_attached');
rollback;

